'ST-UI-001 显示库存搜索框\n\n由 autoSkill 根据录制生成的独立回放脚本；运行它不需要 autoSkill。\n浏览器默认显示，设置 HEADED=0 可隐藏。可用环境变量：BASE_URL、CHROME_BINARY、TIMEOUT、CHROMEDRIVER。\n动作与断言使用共享的定位候选、XPath、iframe 与开放 Shadow DOM 上下文规则。\n断言使用与内置回放相同的轮询、来源状态和持续后置条件语义。\n差异：独立脚本遇到首个失败立即停止；内置回放会继续收集业务断言。\n验证码需要人工输入；登录态复用、运行历史和截图由内置执行器管理，不随脚本导出。'
import os
import time
from urllib.parse import urljoin, urlsplit

from selenium import webdriver

BASE_URL = os.environ.get("BASE_URL", "https://stock.example.invalid").rstrip("/")
TIMEOUT = float(os.environ.get("TIMEOUT", "10"))
RAND = os.environ.get("RAND") or os.urandom(3).hex()  # unique text for the data this run creates


class Tabs:
    @staticmethod
    def destination(url):
        # Popup destinations are hints, never credentials or one-time login parameters.
        import re
        from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

        parts = urlsplit(url)
        sensitive = r"token|secret|password|passwd|authorization|api.?key|credential|session|signature|^(code|key|ticket|state)$"
        query = [(k, v) for k, v in parse_qsl(parts.query, keep_blank_values=True) if not re.search(sensitive, k, re.IGNORECASE)]
        return urlunsplit((parts.scheme, parts.netloc.rsplit('@', 1)[-1], parts.path, urlencode(query), ''))

    def __init__(self, handles, activate, create, close, url, ready, current):
        self.handles, self.activate, self.create = handles, activate, create
        self.close, self.url, self.ready = close, url, ready
        self.known = {"t1": current}
        self.current = current

    def select(self, tab, timeout):
        handle = self.known.get(tab)
        if handle is None or handle not in self.handles():
            raise ValueError("标签页不存在或已关闭：" + tab)
        self.activate(handle)
        self.current = handle
        self.ready(handle, timeout)
        return handle

    def action(self, step, timeout):
        op, tab = step["action"], step.get("tab")
        if op == "tab_new":
            if tab in self.known:
                raise ValueError("标签页编号不能重复使用：" + tab)
            self.known[tab] = self.create(step["url"])
            return self.select(tab, timeout)
        if op == "tab_close":
            handle = self.known.get(tab)
            if handle is None or handle not in self.handles():
                raise ValueError("标签页不存在或已关闭：" + tab)
            if step["active"] == tab or len(self.handles()) <= 1:
                raise ValueError("不能关闭最后一个标签页；请结束或取消录制")
            self.close(handle)
            return self.select(step["active"], timeout)
        if op == "tab_switch":
            return self.select(tab, timeout)
        return self.current

    def sync(self, change, timeout):
        if not change:
            return self.current
        deadline = time.monotonic() + timeout
        pending = list(change.get("opened", []))
        closed = change.get("closed", [])
        if any(tab not in self.known for tab in closed):
            raise ValueError("要关闭的标签页从未打开")
        while True:
            live = self.handles()
            unknown = [h for h in live if h not in self.known.values()]
            for item in pending[:]:
                # Use the recorded destination to disambiguate simultaneous popups.
                matches = [h for h in unknown if item.get("url") and self.destination(self.url(h)) == self.destination(item["url"])]
                if len(matches) == 1:
                    handle = matches[0]
                elif len(unknown) == 1 and len(pending) == 1:
                    handle = unknown[0]
                else:
                    continue
                if item["id"] in self.known:
                    raise ValueError("标签页编号不能重复使用：" + item["id"])
                self.known[item["id"]] = handle
                pending.remove(item)
                unknown.remove(handle)
            gone = all(self.known.get(tab) not in live for tab in closed)
            if not pending and gone:
                return self.select(change["active"], max(0.1, deadline - time.monotonic()))
            if time.monotonic() >= deadline:
                raise TimeoutError("等待新标签页打开或关闭超时；没有切到其他页面代替")
            # Playwright needs its event loop pumped while waiting for popup events.
            self.ready(None, 0.05)


def selenium_tabs(driver):
    handles = driver.window_handles
    if not handles:
        raise ValueError("所有标签页都已关闭")
    try:
        current = driver.current_window_handle
    except Exception:  # noqa: BLE001  # Closed-window failures vary by browser adapter; retain the existing fallback.
        current = handles[0]
    for handle in handles:
        if handle != current:
            driver.switch_to.window(handle)
            driver.close()
    driver.switch_to.window(current)

    def create(url):
        driver.switch_to.new_window("tab")
        driver.get(url)
        return driver.current_window_handle

    def close(handle):
        driver.switch_to.window(handle)
        driver.close()

    def url(handle):
        try:
            old = driver.current_window_handle
        except Exception:  # noqa: BLE001  # A closing window can fail through different driver exception types.
            old = None
        driver.switch_to.window(handle)
        value = driver.current_url
        if old in driver.window_handles:
            driver.switch_to.window(old)
        return value

    def ready(handle, timeout):
        if handle is None:
            time.sleep(timeout)
            return
        deadline = time.monotonic() + timeout
        while driver.execute_script("return document.readyState") == "loading":
            if time.monotonic() >= deadline:
                raise TimeoutError("标签页加载超时")
            time.sleep(0.05)

    def activate(handle):
        return driver.switch_to.window(handle)

    return Tabs(lambda: driver.window_handles, activate, create,
                close, url, ready, current)



class _IR:
    expand = staticmethod(lambda value: value)
    describe = staticmethod(lambda step: step.get("name", step.get("assertion", "断言")))
    describe_locator = staticmethod(str)


class _Secrets:
    resolve = staticmethod(lambda value: value)


class _Captcha:
    solve = staticmethod(lambda _image: input("请输入验证码："))


ir, secrets, captcha = _IR(), _Secrets(), _Captcha()
POLL, PRIMARY_GRACE, LOCATOR, STEP_TIMEOUT = 0.1, 1.5, "locator_not_found", "timeout"


def locators(step: dict) -> list[dict]:
    """All locator candidates of a step, best first."""
    found = [dict(item) for item in step.get('locators', [])]
    if 'selector' in step:
        selector = step['selector']
        found.append({'by': 'xpath', 'value': selector[6:]} if selector.startswith('xpath=') else {'by': 'css', 'value': selector})
    if 'placeholder' in step:
        found.append({'by': 'placeholder', 'value': step['placeholder']})
    if 'role' in step:
        found.append({'by': 'role', 'role': step['role'], 'name': step.get('name')})
    return found
ir.locators = locators

def absolute_url(url: str, base_url: str) -> str:
    """Cases may store a path; the project's target address makes it absolute."""
    if urlsplit(url).scheme:
        return url
    if not base_url:
        raise ValueError('用例使用了相对地址，但项目没有设置目标地址')
    return urljoin(base_url.rstrip('/') + '/', url.lstrip('/'))
ir.absolute_url = absolute_url

def check_origin(url: str, allowed: list[str]) -> None:
    """Validate URL shape; legacy allowed_origins no longer limits site traffic."""
    parts = urlsplit(url)
    if parts.scheme in ('about', 'data', 'blob'):
        return
    if parts.scheme not in ('http', 'https') or not parts.hostname or parts.username or parts.password:
        shown = f'{parts.scheme}://{parts.hostname}' + (f':{parts.port}' if parts.port else '') if parts.hostname else parts.scheme + ':'
        raise PermissionError(f'地址 {shown} 格式无效或含内嵌凭据')
ir.check_origin = check_origin

class StepError(Exception):

    def __init__(self, category: str, message: str):
        super().__init__(message)
        self.category = category

def check_cancel(driver) -> None:
    """Managed runs supply a read-only cancellation hook; standalone drivers do not need one."""
    requested = getattr(driver, 'cancel_requested', None)
    if requested and requested():
        raise StepError('cancelled', '运行已取消')

def choose_locator(driver, step: dict, timeout: float, need: bool=True):
    """Return (locator, index) of the first candidate that matches; index > 0 means a fallback was used."""
    candidates = ir.expand(ir.locators(step))
    if 'context' in step:
        candidates = [{**candidate, 'context': ir.expand(step['context'])} for candidate in candidates]
    if not candidates:
        return (None, 0)
    start = time.monotonic()
    last_error = None
    while True:
        check_cancel(driver)
        elapsed = time.monotonic() - start
        pool = candidates[:1] if need and elapsed < PRIMARY_GRACE else candidates
        for index, locator in enumerate(pool):
            try:
                if driver.count(locator) > locator.get('nth', 0):
                    return (locator, index)
            except StepError as error:
                if not need:
                    raise
                last_error = error
        if not need or elapsed >= timeout:
            if need:
                if last_error:
                    raise last_error
                raise StepError(LOCATOR, '页面上找不到：' + ' / '.join((ir.describe_locator(c) for c in candidates)))
            return (candidates[0], 0)
        time.sleep(POLL)

def _same(expected, actual) -> bool:
    return ' '.join(str(expected).split()) == ' '.join(str(actual).split())

def evaluate(driver, step: dict, locator) -> tuple[bool, object]:
    """One reading of an assertion: (passed, actual value)."""
    op, expected = (step['assertion'], ir.expand(step.get('expected')))
    if op == 'url':
        return (driver.url() == expected, driver.url())
    if op == 'url_contains':
        return (str(expected) in driver.url(), driver.url())
    if op == 'title':
        return (_same(expected, driver.title()), driver.title())
    count = driver.count(locator)
    if op == 'count':
        return (count == expected, count)
    if op == 'min_count':
        return (count >= expected, count)
    if op == 'hidden':
        visible = count > locator.get('nth', 0) and driver.read(locator, 'visible')
        return (not visible, '可见' if visible else '不可见')
    if count <= locator.get('nth', 0):
        return (False, '未找到元素')
    if op == 'visible':
        visible = driver.read(locator, 'visible')
        return (bool(visible), '可见' if visible else '不可见')
    if op == 'checked':
        actual = driver.read(locator, 'checked')
        return (actual == bool(step.get('expected', True)), actual)
    if op == 'attribute':
        actual = driver.read(locator, 'attribute', step['attribute'])
        wanted = str(expected)
        if step['attribute'] == 'class' and actual is not None:
            return (wanted in str(actual).split(), actual)
        return (actual is not None and str(actual) == wanted, actual)
    actual = driver.read(locator, 'value' if op == 'value' else 'text')
    if op == 'contains':
        return (str(expected) in str(actual), actual)
    return (_same(expected, actual), actual)

def _prepare_assertion(step: dict) -> dict:
    """Resolve runtime expectations before polling; configuration errors are not business failures."""
    step = {**step, 'expected': secrets.resolve(ir.expand(step.get('expected', True)))}
    if step['assertion'] in ('count', 'min_count') and isinstance(step['expected'], str):
        if not step['expected'].isdigit():
            raise ValueError('count 断言的动态期望必须是非负整数')
        step['expected'] = int(step['expected'])
    if 'transition_from' in step:
        step['transition_from'] = _prepare_assertion({'locators': ir.locators(step), 'context': step.get('context', []), **step['transition_from']})
    return step

def _read_assertion(driver, step: dict) -> tuple[bool, object, int]:
    try:
        locator, selected = choose_locator(driver, step, 0, need=False)
        passed, actual = evaluate(driver, step, locator)
        return (passed, actual, selected)
    except Exception as error:
        if isinstance(error, StepError) and error.category == 'cancelled':
            raise
        return (False, '读取失败：' + (str(error) if isinstance(error, StepError) else type(error).__name__), 0)

def _poll_assertion(driver, step: dict, timeout: float) -> dict:
    """Observe a transition and/or continuous postcondition without executing the action again."""
    started = time.monotonic()
    stable = float(step.get('stable_for_seconds', 0))
    budget = max(float(step.get('timeout_seconds', timeout)), stable)
    source = step.get('transition_from')
    phase, since, fallback, source_actual = ('transition_from' if source else 'postcondition', None, 0, None)
    while True:
        check_cancel(driver)
        passed, actual, selected = _read_assertion(driver, source if phase == 'transition_from' else step)
        check_cancel(driver)
        fallback = max(fallback, selected)
        now = time.monotonic()
        if phase == 'transition_from':
            source_actual = actual
            if passed:
                phase = 'postcondition'
                continue
        else:
            since = (now if since is None else since) if passed else None
            if passed and now - since >= stable:
                phase = 'complete'
                break
            if not passed and step.get('mode') == 'always':
                break
        if now - started >= budget:
            passed = False
            break
        time.sleep(min(POLL, max(0, budget - (now - started))))
    row = {'passed': bool(passed), 'expected': step.get('expected', True), 'actual': actual, 'phase': phase, 'elapsed_ms': round((now - started) * 1000), 'timeout_seconds': budget, 'stable_for_seconds': stable, 'continuous_ms': round((now - since) * 1000) if since is not None else 0}
    if source:
        row['source_observation'] = {'expected': source.get('expected', True), 'actual': source_actual, 'observed': phase != 'transition_from'}
    if fallback:
        row['fallback'] = True
    return row

def check(driver, step: dict, timeout: float) -> dict:
    """Check the declared oracle with an explicit deadline and preserve the observation separately."""
    name = step.get('name') or ir.describe(step)
    result = _poll_assertion(driver, _prepare_assertion(step), timeout)
    return {'name': name, **result, 'oracle': step.get('oracle', {'source': 'explicit'})}

def navigate(action, *args) -> None:
    """Load a page; a load that runs out of time is reported as such, not as a missing element."""
    try:
        action(*args)
    except Exception as error:
        if 'Timeout' in type(error).__name__:
            raise StepError(STEP_TIMEOUT, '页面没有在限定时间内加载完成；页面本身很慢时可以调大：autoskill project update <项目> --page-load <秒>') from None
        raise

def perform(driver, step: dict, base_url: str, allowed: list[str], timeout: float) -> bool:
    """Run one action. Returns True when a fallback locator had to be used."""
    check_cancel(driver)
    op = step['action']
    timeout = float(step.get('timeout_seconds', timeout))
    if op.startswith('tab_'):
        tab_step = dict(step)
        if op == 'tab_new':
            tab_step['url'] = ir.absolute_url(step['url'], base_url)
            ir.check_origin(tab_step['url'], allowed)
        driver.tab_action(tab_step, timeout)
        return False
    if op == 'goto':
        url = ir.absolute_url(step['url'], base_url)
        ir.check_origin(url, allowed)
        navigate(driver.goto, url)
        return False
    if op == 'reload':
        navigate(driver.reload)
        return False
    need = op != 'wait_hidden'
    locator, fallback = choose_locator(driver, step, timeout, need=need)
    if op == 'press':
        driver.press(locator, step['key'])
    elif op in ('fill', 'type', 'select'):
        driver.act(locator, op, secrets.resolve(ir.expand(step['value'])))
    elif op == 'captcha':
        picture, _ = choose_locator(driver, {'locators': step['image'], 'context': step.get('image_context', step.get('context', []))}, timeout)
        driver.act(locator, 'fill', captcha.solve(driver.image(picture)))
    elif op in ('wait_visible', 'wait_hidden'):
        wanted = op == 'wait_visible'
        deadline = time.monotonic() + timeout
        while True:
            check_cancel(driver)
            locator, selected = choose_locator(driver, step, 0, need=False)
            fallback = max(fallback, selected)
            visible = driver.count(locator) > locator.get('nth', 0) and bool(driver.read(locator, 'visible'))
            if visible == wanted:
                break
            if time.monotonic() >= deadline:
                raise StepError(STEP_TIMEOUT, f'等待超时：{ir.describe(step)}')
            time.sleep(POLL)
    else:
        driver.act(locator, op, None)
    return bool(fallback)

DOM_JS = '(function (root = document) {\n  // DOM helpers shared by the Selenium driver (element lookup) and the recorder\n  // (turning the element an agent touched into stable locator candidates).\n  // Lookup mirrors Playwright\'s getBy* locators closely enough that one recorded\n  // step resolves to the same element in both engines.\n  const norm = (s) => (s || \'\').replace(/\\s+/g, \' \').trim();\n  const FIELD = /^(INPUT|TEXTAREA|SELECT)$/;\n  const INPUT_ROLES = {\n    button: \'button\', submit: \'button\', reset: \'button\', image: \'button\', checkbox: \'checkbox\',\n    radio: \'radio\', range: \'slider\', number: \'spinbutton\', search: \'searchbox\', hidden: null,\n  };\n  const TAG_ROLES = {\n    BUTTON: \'button\', TEXTAREA: \'textbox\', H1: \'heading\', H2: \'heading\', H3: \'heading\', H4: \'heading\',\n    H5: \'heading\', H6: \'heading\', LI: \'listitem\', UL: \'list\', OL: \'list\', NAV: \'navigation\', MAIN: \'main\',\n    TABLE: \'table\', TR: \'row\', TD: \'cell\', TH: \'columnheader\', OPTION: \'option\', IMG: \'img\',\n    DIALOG: \'dialog\', PROGRESS: \'progressbar\', FORM: \'form\', ARTICLE: \'article\',\n  };\n  function role(el) {\n    const explicit = (el.getAttribute(\'role\') || \'\').trim().split(/\\s+/)[0];\n    if (explicit) return explicit;\n    if (el.tagName === \'A\') return el.hasAttribute(\'href\') ? \'link\' : null;\n    if (el.tagName === \'INPUT\') {\n      const type = (el.getAttribute(\'type\') || \'text\').toLowerCase();\n      if (type in INPUT_ROLES) return INPUT_ROLES[type];\n      return el.hasAttribute(\'list\') ? \'combobox\' : \'textbox\';\n    }\n    if (el.tagName === \'SELECT\') return el.multiple || el.size > 1 ? \'listbox\' : \'combobox\';\n    return TAG_ROLES[el.tagName] || null;\n  }\n  function labelText(el) {\n    const ids = el.getAttribute(\'aria-labelledby\');\n    if (ids) {\n      const text = norm(ids.split(/\\s+/).map((id) => (root.querySelector(\'#\' + CSS.escape(id)) || {}).textContent || \'\