        keys = [getattr(Keys, KEYS[part]) if part in KEYS else part for part in key.split('+')]
        if locator:
            self._one(locator).send_keys(*keys)
            return
        chain = ActionChains(self.wd)
        for modifier in keys[:-1]:
            chain.key_down(modifier)
        chain.send_keys(keys[-1])
        for modifier in reversed(keys[:-1]):
            chain.key_up(modifier)
        chain.perform()

def execute(driver, step):
    fallback = perform(driver, step, BASE_URL, [], TIMEOUT)
    if fallback:
        print("已使用备选定位")
    return fallback


def verify(driver, step):
    result = check(driver, step, TIMEOUT)
    if not result["passed"]:
        raise AssertionError(f"{result['name']}：期望 {result['expected']!r}，实际 {result['actual']!r}；"
                             f"阶段 {result['phase']}，已等待 {result['elapsed_ms']} ms")
    return result


